// Writes migrations/0002_research_seed.sql: the research-modelled games each mode starts with
// (see SEED in public/js/community.js for the studies and how the games are spread). They go
// into their own histogram rows, 'dial:research' and 'sing:research', never into the games table.
// Usage: node tools/make-seed.js     (or: npm run seed). tests/test-pitch.js checks the file is current.
import fs from 'node:fs';
import { SEED, SEED_GAMES, seedAverages, seedBins } from '../public/js/community.js';

export function seedSql() {
  const lines = [
    '-- Generated by tools/make-seed.js from SEED in public/js/community.js. Do not edit by hand.',
    `-- ${SEED_GAMES} research-modelled games per mode, kept apart from real players' games and labelled`,
    '-- as research wherever they are shown. The comparison drops them once a mode has SEED_UNTIL real games.'
  ];
  for (const mode of Object.keys(SEED)) {
    const avgs = seedAverages(mode);
    lines.push(`-- ${mode}: ${SEED[mode].about}; game averages ${avgs[0].toFixed(1)}–${avgs[avgs.length - 1].toFixed(1)}¢`);
    lines.push(`INSERT INTO histogram (mode, n, bins) VALUES ('${mode}:research', ${SEED_GAMES}, '${JSON.stringify(seedBins(mode))}');`);
  }
  return lines.join('\n') + '\n';
}

if (process.argv[1] && process.argv[1].endsWith('make-seed.js')) {
  fs.writeFileSync('migrations/0002_research_seed.sql', seedSql());
  console.log('Wrote migrations/0002_research_seed.sql');
}
